library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.wishbone_pkg.all;
use work.wbgenplus_pkg.all;
use work.genram_pkg.all;
use work.reset_comment_auto_pkg.all;

entity reset_comment_auto is
generic(
  g_lanes : natural := 4  --lanes, 25% each
);
Port(
  clk_sys_i   : std_logic;                                -- Clock input for sys domain
  rst_sys_n_i : std_logic;                                -- Reset input (active low) for sys domain
  error_i     : in  std_logic_vector(1-1 downto 0);       -- Error control
  pct_i       : in  std_logic_vector(4-1 downto 0);       -- load 50%, %s %d %% stay literal
  pct_V_i     : in  std_logic_vector(1-1 downto 0);       -- Valid flag - pct
  stall_i     : in  std_logic_vector(1-1 downto 0);       -- flow control
  all_ones_o  : out std_logic_vector(8-1 downto 0);       -- reset to ones, 100% sure
  all_zero_o  : out std_logic_vector(8-1 downto 0);       -- reset to zeroes
  hex_rst_o   : out std_logic_vector(16-1 downto 0);      -- hex reset
  pct_RD_o    : out std_logic_vector(1-1 downto 0);       -- Read enable flag - pct
  pct_w_o     : out std_logic_vector(g_lanes-1 downto 0); -- atomic 10% pulse
  
  ctrl_i      : in  t_wishbone_slave_in;
  ctrl_o      : out t_wishbone_slave_out

  
);
end reset_comment_auto;

architecture rtl of reset_comment_auto is

  signal s_pop, s_push    : std_logic;
  signal s_empty, s_full  : std_logic;
  signal r_e_wait, s_e_p  : std_logic;
  signal s_stall          : std_logic;
  signal s_valid,
         s_valid_ok,
         r_valid_check    : std_logic;
  signal r_ack            : std_logic;
  signal r_err            : std_logic;
  signal s_e, r_e, s_w    : std_logic;
  signal s_d              : std_logic_vector(32-1 downto 0);
  signal s_s              : std_logic_vector(4-1 downto 0);
  signal s_a              : std_logic_vector(3-1 downto 0);
  signal s_a_ext,
         r_a_ext0,
         r_a_ext1         : std_logic_vector(5-1 downto 0);
  signal r_error          : std_logic_vector(1-1 downto 0)        := std_logic_vector(to_unsigned(0, 1)); -- Error
  signal s_error_i        : std_logic_vector(1-1 downto 0)        := (others => '0');                     -- Error control
  signal s_stall_i        : std_logic_vector(1-1 downto 0)        := (others => '0');                     -- flow control
  signal r_all_ones       : std_logic_vector(8-1 downto 0)        := (others => '1');                     -- reset to ones, 100% sure
  signal r_all_zero       : std_logic_vector(8-1 downto 0)        := std_logic_vector(to_unsigned(0, 8)); -- reset to zeroes
  signal r_hex_rst        : std_logic_vector(16-1 downto 0)       := x"beef";                             -- hex reset
  signal r_pct_RD         : std_logic_vector(1-1 downto 0)        := std_logic_vector(to_unsigned(0, 1)); -- Read enable flag - pct
  signal r_pct_V          : std_logic_vector(1-1 downto 0)        := (others => '0');                     -- Valid flag - pct
  signal s_pct_V_i        : std_logic_vector(1-1 downto 0)        := (others => '0');                     -- Valid flag - pct
  signal r_pct            : std_logic_vector(4-1 downto 0)        := (others => '0');                     -- load 50%, %s %d %% stay literal
  signal s_pct_i          : std_logic_vector(4-1 downto 0)        := (others => '0');                     -- load 50%, %s %d %% stay literal
  signal r_pct_w          : std_logic_vector(g_lanes-1 downto 0)  := (others => '0');                     -- atomic 10% pulse


begin

  sp : wb_skidpad
  generic map(
    g_adrbits   => 3
  )
  Port map(
    clk_i        => clk_sys_i,
    rst_n_i      => rst_sys_n_i,
    push_i       => s_push,
    pop_i        => s_pop,
    full_o       => s_full,
    empty_o      => s_empty,
    adr_i        => ctrl_i.adr(4 downto 2),
    dat_i        => ctrl_i.dat,
    sel_i        => ctrl_i.sel,
    we_i         => ctrl_i.we,
    adr_o        => s_a,
    dat_o        => s_d,
    sel_o        => s_s,
    we_o         => s_w
  );

  validmux: with to_integer(unsigned(s_a_ext)) select
  s_valid <= 
  s_pct_V_i(0)  when c_pct_GET, -- 
  '1'           when others;
  
  s_valid_ok      <=  r_valid_check and s_valid;
  s_e_p           <=  r_e or r_e_wait;
  s_a_ext         <= s_a & "00";
  s_stall         <= s_full;
  s_push          <= ctrl_i.cyc and ctrl_i.stb and not s_stall;
  s_e             <= not (s_empty or s_e_p);
  s_pop           <= s_valid_ok;
  ctrl_o.stall    <= s_stall;
  
  s_error_i   <= error_i;
  s_stall_i   <= stall_i;
  all_ones_o  <= r_all_ones;
  all_zero_o  <= r_all_zero;
  hex_rst_o   <= r_hex_rst;
  pct_RD_o    <= r_pct_RD;
  s_pct_V_i   <= pct_V_i;
  s_pct_i     <= pct_i;
  pct_w_o     <= r_pct_w;
  
  ctrl : process(clk_sys_i)
  begin
    if rising_edge(clk_sys_i) then
      if(rst_sys_n_i = '0') then
        r_e           <= '0';
        r_e_wait      <= '0';
        r_valid_check <= '0';
        r_error     <= std_logic_vector(to_unsigned(0, 1));
        r_all_ones  <= (others => '1');
        r_all_zero  <= std_logic_vector(to_unsigned(0, 8));
        r_hex_rst   <= x"beef";
        r_pct_RD    <= std_logic_vector(to_unsigned(0, 1));
        r_pct       <= (others => '0');
        r_pct_w     <= (others => '0');
      else
        r_e           <= s_e;
        r_a_ext0      <= s_a_ext;
        r_a_ext1      <= r_a_ext0;
        r_e_wait      <= s_e_p and not s_valid_ok;
        r_valid_check <= (r_valid_check or (s_e_p and not stall_i(0))) and not s_valid_ok;
        r_ack         <= s_pop and not (error_i(0) or r_error(0));
        r_err         <= s_pop and     (error_i(0) or r_error(0));
        ctrl_o.ack    <= r_ack;
        ctrl_o.err    <= r_err;
        
        
        if stall_i = "0" then
          r_error   <= (others => '0');
          r_pct_RD  <= (others => '0');
          r_pct_w   <= (others => '0');
        end if;
        
        if s_pct_V_i  = "1" then r_pct  <= s_pct_i; end if; -- 
        
        
        if(s_e = '1') then
          if(s_w = '1') then
            -- WISHBONE WRITE ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_all_ones_RW  => r_all_ones <= f_wb_wr(r_all_ones, s_d, s_s, "owr");  -- 
              when c_all_zero_RW  => r_all_zero <= f_wb_wr(r_all_zero, s_d, s_s, "owr");  -- 
              when c_hex_rst_RW   => r_hex_rst  <= f_wb_wr(r_hex_rst, s_d, s_s, "owr");   -- 
              when c_pct_w_CLR    => r_pct_w    <= f_wb_wr(r_pct_w, s_d, s_s, "clr");     -- 
              when c_pct_w_SET    => r_pct_w    <= f_wb_wr(r_pct_w, s_d, s_s, "set");     -- 
              when others         => r_error    <= "1";
            end case;
          else
            -- WISHBONE READ ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_all_ones_RW  => null;
              when c_all_zero_RW  => null;
              when c_hex_rst_RW   => null;
              when c_pct_GET      => null;
              r_pct_RD <= (others => '1');
              when others         => r_error <= "1";
            end case;
          end if; -- s_w
        end if; -- s_e
        
        case to_integer(unsigned(r_a_ext1)) is
          when c_all_ones_RW  => ctrl_o.dat <= std_logic_vector(resize(unsigned(r_all_ones), ctrl_o.dat'length));   -- 
          when c_all_zero_RW  => ctrl_o.dat <= std_logic_vector(resize(unsigned(r_all_zero), ctrl_o.dat'length));   -- 
          when c_hex_rst_RW   => ctrl_o.dat <= std_logic_vector(resize(unsigned(r_hex_rst), ctrl_o.dat'length));    -- 
          when c_pct_GET      => ctrl_o.dat <= std_logic_vector(resize(unsigned(r_pct), ctrl_o.dat'length));        -- 
          when others         => ctrl_o.dat <= (others => 'X');
        end case;

        
      end if; -- rst
    end if; -- clk edge
  end process;

end rtl;
